mapper.sql:
WHERE ek.deleted = 0
AND (k.code LIKE #{f.keyword} OR k.name LIKE #{f.keyword})
AND ek.year = #{f.year}
AND ek.period_code = #{f.period}
AND k.perspective_id = #{f.perspectiveId}
AND ek.status = #{f.status}
AND ek.result_type = #{f.resultType}

  AND EXISTS (SELECT 1 FROM evaluation_result rs WHERE rs.evaluation_kpi_id = ek.id AND rs.deleted = 0
    )

mapper.select:
SELECT DISTINCT ek.id FROM evaluation_kpi ek JOIN kpi_component c ON c.kpi_id = ek.kpi_id AND c.deleted = 0 AND c.source = 'API'
WHERE ek.deleted = 0 AND ek.year = #{year} AND ek.status <> 'CHOT_KQ_R2'
  AND ek.period_code IN #{p}

mapper.sql:
WHERE r.deleted = 0
AND r.evaluation_kpi_id = #{f.evalKpiId}
AND r.id IN #{i}
AND r.org_unit_id = #{f.unitId}
AND ek.kpi_id = #{f.kpiId}
AND ek.year = #{f.year}
AND ek.period_code = #{f.period}
AND (o.code LIKE #{f.keyword} OR o.name LIKE #{f.keyword} OR k.code LIKE #{f.keyword} OR k.name LIKE #{f.keyword})
AND (o.code LIKE #{f.unitKeyword} OR o.name LIKE #{f.unitKeyword})
AND r.status = #{f.status}
AND r.status IN #{s}
AND r.rating = #{f.rating}
AND k.perspective_id = #{f.perspectiveId}
AND ek.result_type = #{f.resultType}
AND (r.final_result IS NOT NULL OR r.score IS NOT NULL)
AND k.parent_id IS NULL

mapper.update:
UPDATE evaluation_result SET kpi_result = #{kpiResult}, prev_adjustment = #{prevAdjustment}, final_result = #{finalResult},
  completion_rate = #{completionRate}, year_completion_rate = #{yearCompletionRate}, score = #{score}, bsc_score = #{bscScore},
  rating = #{rating}, calc_error = #{calcError}, result_before_adjust = #{resultBeforeAdjust}, result_after_adjust = #{resultAfterAdjust}
WHERE id = #{id}

mapper.insert:
INSERT INTO evaluation_component_value (result_id, component_id, source, unit_proposed_value, unit_proposed_adjustment, created_by, updated_by)
SELECT #{resultId}, c.id, c.source, #{value}, #{adjustment}, 'system', 'system' FROM kpi_component c WHERE c.id = #{componentId}
ON DUPLICATE KEY UPDATE unit_proposed_value = VALUES(unit_proposed_value), unit_proposed_adjustment = VALUES(unit_proposed_adjustment), updated_at = NOW(3)

INSERT INTO evaluation_component_value (result_id, component_id, source, adjustment, created_by, updated_by)
SELECT #{resultId}, c.id, c.source, #{adjustment}, 'system', 'system' FROM kpi_component c WHERE c.id = #{componentId}
ON DUPLICATE KEY UPDATE adjustment = VALUES(adjustment), updated_at = NOW(3)
